-- ==========================================================================
-- FC9 RECUT, ASSOCIATE TIER (beginner): Corrosion & Integrity (corrosion)
-- question bank brought to engines 16fd6c9 (#231).
--
-- WHY. Engines #231 (canonical 16fd6c9) adds a two-line comment to
-- engines/facilities/corrosion.js and moves no value. The LIVE FC9 bank quoted
-- facts about the engine SOURCE FILE ("783 lines", "five past-tense comment
-- lines", "one line in 157"), which the re-vendor makes false. Questions keyed
-- on a file's line count test nothing about corrosion, so the recut drops the
-- count wherever it was incidental and replaces the one question that keyed on
-- it with a question about what the sour flag tells an engineer.
--
-- WHAT MOVES. 1 of the 132 Associate questions, 1 with a changed keyed answer TEXT and 0 with a changed answer INDEX. No ord, no
-- module key, no scope and no row count moves, so every question id and every
-- learner attempt against it survives.
-- Fields rewritten: 1 options (1 field edits).
--
-- GUARDS. Each row is addressed by its stable identity (app_slug, tier, scope,
-- module_key, ord) and must match EITHER its published text exactly, in which
-- case it is updated, OR the recut text exactly, in which case it is already
-- applied and left alone. Anything else raises and the transaction rolls back.
-- Every update asserts it touched exactly 1 row, and the tier must still hold
-- 132 questions at the end.
--
-- The published strings are the rows 20260925_fc9_corrosion_beginner_deep.sql
-- wrote (APPLIED 2026-09-19), regenerated byte for byte from the committed banks
-- at origin/main d54538463. See docs/fc9-231-recut/RECUT-fc9-corrosion.json.
--
-- SAFE TO RE-RUN. A second run finds every row already carrying the recut
-- text and updates nothing.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
begin

  -- module m01-what-this-screen-answers-and-what-it-withdrew ord 3: options KEYED ANSWER TEXT CHANGED
  select case
           when prompt = 'The digest proves the withdrawn severity region is genuinely gone three separate ways. Which of these is one of them?' and options = '["None of the three material guidance strings and neither standard name appears anywhere in the 783 lines of the engine source.", "The function is still exported, and every call to it now returns an error object that names the standard it is no longer willing to cite.", "The vendored golden carries no row for the region, so a case that asked for one would fail the suite.", "The studio hides the region rows behind a disclosure, so nothing reaches the screen even when the field is populated."]'::jsonb and answer_index = 0 and explanation = 'The three checks are that `sourServiceRegion` is not exported so typeof it is undefined, that neither standard name nor any of the three guidance strings is anywhere in the source, and that no returned string in three whole screenings names either standard.' then 'old'
           when prompt = 'The digest proves the withdrawn severity region is genuinely gone three separate ways. Which of these is one of them?' and options = '["None of the three material guidance strings and neither standard name appears anywhere in the engine source.", "The function is still exported, and every call to it now returns an error object that names the standard it is no longer willing to cite.", "The vendored golden carries no row for the region, so a case that asked for one would fail the suite.", "The studio hides the region rows behind a disclosure, so nothing reaches the screen even when the field is populated."]'::jsonb and answer_index = 0 and explanation = 'The three checks are that `sourServiceRegion` is not exported so typeof it is undefined, that neither standard name nor any of the three guidance strings is anywhere in the source, and that no returned string in three whole screenings names either standard.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-this-screen-answers-and-what-it-withdrew'::text and ord = 3;
  if v_state is null then raise exception 'FC9 recut refused: no row for module m01-what-this-screen-answers-and-what-it-withdrew ord 3'; end if;
  if v_state = 'other' then raise exception 'FC9 recut refused: module m01-what-this-screen-answers-and-what-it-withdrew ord 3 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'The digest proves the withdrawn severity region is genuinely gone three separate ways. Which of these is one of them?', options = '["None of the three material guidance strings and neither standard name appears anywhere in the engine source.", "The function is still exported, and every call to it now returns an error object that names the standard it is no longer willing to cite.", "The vendored golden carries no row for the region, so a case that asked for one would fail the suite.", "The studio hides the region rows behind a disclosure, so nothing reaches the screen even when the field is populated."]'::jsonb, answer_index = 0, explanation = 'The three checks are that `sourServiceRegion` is not exported so typeof it is undefined, that neither standard name nor any of the three guidance strings is anywhere in the source, and that no returned string in three whole screenings names either standard.'
     where app_slug = 'corrosion' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm01-what-this-screen-answers-and-what-it-withdrew'::text and ord = 3;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'FC9 recut refused: module m01-what-this-screen-answers-and-what-it-withdrew ord 3 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_count from public.academy_quiz_questions where app_slug = 'corrosion' and tier = 'beginner';
  if v_count <> 132 then raise exception 'FC9 recut refused: corrosion beginner holds % questions, expected 132', v_count; end if;
  raise notice 'FC9 recut beginner: % of 1 rows updated, % already recut', v_updated, 1 - v_updated;
end
$$;
